package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.messaging;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;@Entity@Table(name="moderation_processed_events")public class ProcessedEventEntity{@Id private UUID eventId;@Column(name="event_type",nullable=false,length=120)private String eventType;@Column(name="processed_at",nullable=false)private Instant processedAt;public UUID getEventId(){return eventId;}public void setEventId(UUID v){eventId=v;}public String getEventType(){return eventType;}public void setEventType(String v){eventType=v;}public Instant getProcessedAt(){return processedAt;}public void setProcessedAt(Instant v){processedAt=v;}}
